 14	  createTanStackRouter({
 15	    context: {
 16	      loadDocsPage: loadWebsiteDocsPage,
 17	      loadDocsSearch: loadWebsiteDocsSearch,
 18	      loadSettings: loadWebsiteSettings,
 19	    },
