  1	import { RegistryProvider } from "@effect/atom-react";
  2	import {
  3	  createRootRouteWithContext,
  4	  HeadContent,
  5	  Link,
  6	  Outlet,
  7	  Scripts,
  8	  useLoaderData,
  9	} from "@tanstack/react-router";
 10	import type { CalculatorCatalogResponse } from "@taxkit/api-rpc/schemas";
 11	import { Array, Option, Result, Schema } from "effect";
 12	import { createContext, useMemo } from "react";
 13	
 14	import {
 15	  publicSettingsAtom,
 16	  websiteCatalogueAtom,
 17	} from "#/lib/calculator.atoms";
 18	import type { RouterContext } from "#/lib/route-context";
 19	import {
 20	  WebsiteSettingsTransport,
 21	  WebsiteCatalogueTransport,
 22	  WebsiteSubmissionTransport,
 23	} from "#/lib/schemas";
 24	import type { WebsiteSubmission } from "#/lib/schemas";
 25	
 26	import "../styles.css";
 27	
 28	// Only the root route restores this transport. Children receive checked values.
 29	export const WebsiteSubmissionContext = createContext<
 30	  Option.Option<typeof WebsiteSubmission.Type>
 31	>(Option.none());
 32	export const WebsiteCatalogueContext = createContext<
 33	  Option.Option<typeof CalculatorCatalogResponse.Type>
 34	>(Option.none());
 35	
 36	const RootShell = ({ children }: { readonly children: React.ReactNode }) => (
 37	  <html lang="en-AU">
 38	    <head>
 39	      <HeadContent />
 40	    </head>
 41	    <body>
 42	      {children}
 43	      <Scripts />
 44	    </body>
 45	  </html>
 46	);
 47	const RootComponent = () => {
 48	  const data = useLoaderData({ from: "__root__" });
 49	  const settings = useMemo(
 50	    () => Schema.decodeUnknownResult(WebsiteSettingsTransport)(data.settings),
 51	    [data.settings]
 52	  );
 53	  const submission = useMemo(
 54	    () =>
 55	      data.submission === undefined
 56	        ? Option.none<typeof WebsiteSubmission.Type>()
 57	        : Schema.decodeResult(WebsiteSubmissionTransport)(data.submission).pipe(
 58	            Result.getSuccess
 59	          ),
 60	    [data.submission]
 61	  );
 62	  const catalogue = useMemo(
 63	    () =>
 64	      Schema.decodeUnknownResult(WebsiteCatalogueTransport)(
 65	        data.catalogue
 66	      ).pipe(
 67	        Result.match({
 68	          onFailure: () => Option.none<typeof CalculatorCatalogResponse.Type>(),
 69	          onSuccess: Result.getSuccess,
 70	        })
 71	      ),
 72	    [data.catalogue]
 73	  );
 74	  if (Result.isFailure(settings) || Result.isFailure(settings.success)) {
 75	    return (
 76	      <main className="home">
 77	        <h1>TaxKit</h1>
 78	        <p role="alert">
 79	          TaxKit cannot load its settings. Please try again later.
 80	        </p>
 81	      </main>
 82	    );
 83	  }
 84	  const checked = settings.success.success;
 85	  return (
 86	    <RegistryProvider
 87	      key={checked.apiOrigin.href}
 88	      initialValues={[
 89	        [publicSettingsAtom, Option.some(checked)],
 90	        [websiteCatalogueAtom, catalogue],
 91	      ]}
 92	    >
 93	      <WebsiteSubmissionContext.Provider value={submission}>
 94	        <WebsiteCatalogueContext.Provider value={catalogue}>
 95	          <div className="app-shell">
 96	            <a className="skip-link" href="#main-content">
 97	              Skip to content
 98	            </a>
 99	            <nav aria-label="Calculators">
100	              {Option.match(catalogue, {
101	                onNone: () => (
102	                  <p>
103	                    The calculator list could not load. Please reload this page.
104	                  </p>
105	                ),
106	                onSome: (value) => (
107	                  <ul>
108	                    {Array.map(value.calculators, (calculator) => (
109	                      <li key={calculator.calculatorId}>
110	                        {calculator.calculatorId === "au.pay.take-home" ? (
111	                          <Link activeProps={{ "aria-current": "page" }} to="/">
112	                            {calculator.title}
113	                          </Link>
114	                        ) : (
115	                          <Link
116	                            activeProps={{ "aria-current": "page" }}
117	                            to="/calculators/$calculatorId"
118	                            params={{ calculatorId: calculator.calculatorId }}
119	                          >
120	                            {calculator.title}
121	                          </Link>
122	                        )}
123	                      </li>
124	                    ))}
125	                  </ul>
126	                ),
127	              })}
128	              <a href={new URL("/api/docs", checked.apiOrigin).href}>
129	                For developers: API documentation
130	              </a>
131	              <Link activeProps={{ "aria-current": "page" }} to="/agents">
132	                For agents: API access
133	              </Link>
134	              <Link params={{ _splat: "start/quickstart" }} to="/$">
135	                Documentation
136	              </Link>
137	            </nav>
138	            <main id="main-content" tabIndex={-1}>
139	              <Outlet />
140	            </main>
141	          </div>
142	        </WebsiteCatalogueContext.Provider>
143	      </WebsiteSubmissionContext.Provider>
144	    </RegistryProvider>
145	  );
146	};
147	export const Route = createRootRouteWithContext<RouterContext>()({
148	  component: RootComponent,
149	  head: () => ({
150	    meta: [
151	      { charSet: "utf-8" },
152	      { content: "width=device-width, initial-scale=1", name: "viewport" },
153	      { title: "TaxKit" },
154	      {
155	        content:
156	          "Australian take-home pay, pay withholding and annual income tax calculators for 2025–26.",
157	        name: "description",
158	      },
159	    ],
160	  }),
161	  loader: ({ context, abortController, serverContext }) =>
162	    context.loadSettings({
163	      signal: abortController.signal,
164	      submission: serverContext?.submission,
165	    }),
166	  shellComponent: RootShell,
167	});
  1	import {
  2	  createStartHandler,
  3	  defaultStreamHandler,
  4	} from "@tanstack/react-start/server";
  5	import {
  6	  CalculatorRequestBodyPolicy,
  7	  withCalculatorRequestBodyLimit,
  8	} from "@taxkit/api-http/request-boundary";
  9	import {
 10	  CalculatorRequestRateKey,
 11	  calculatorEdgeRateKey,
 12	} from "@taxkit/api-rpc/rate-identity";
 13	import { DocsDiscoveryPath, DocsPublicPagePath } from "@taxkit/content/schemas";
 14	import { AuAnnualTaxCalculatorId } from "@taxkit/rules-au-income-tax/schemas";
 15	import { AuPayCalculatorId } from "@taxkit/rules-au-pay/schemas";
 16	import { Effect, ErrorReporter, Match, Schema } from "effect";
 17	import {
 18	  Headers as EffectHeaders,
 19	  HttpServerError,
 20	  HttpServerRequest,
 21	  HttpServerResponse,
 22	} from "effect/http";
 23	
 24	import { WebsiteAnalyticsRelay } from "./lib/analytics/relay/service";
 25	import { WebsiteServerFunctionBase } from "./lib/config";
 26	import { withDocsRepresentation } from "./lib/docs/markdown.response.server";
 27	import {
 28	  takeHomeRequestFromForm,
 29	  annualTaxRequestFromForm,
 30	  AnnualTaxForm,
 31	  TakeHomeForm,
 32	  WebsiteInputError,
 33	} from "./lib/form.boundary";
 34	import type { WebsiteCalculatorForm } from "./lib/form.boundary";
 35	import {
 36	  WebsiteDocsSearchFunctionPath,
 37	  WebsiteDocsPageFunctionPath,
 38	  WebsiteSettingsFunctionPath,
 39	} from "./lib/loaders";
 40	import { appRuntime } from "./lib/runtime.server";
 41	import {
 42	  WebsiteDocsSearchHeader,
 43	  WebsiteSubmission,
 44	  WebsiteSubmissionTransport,
 45	} from "./lib/schemas";
 46	import type { WebsiteServerRenderContext } from "./lib/schemas";
 47	import { WebsiteServerApplication } from "./lib/service.server";
 48	
 49	const render = createStartHandler<{
 50	  server: { requestContext: WebsiteServerRenderContext };
 51	}>(defaultStreamHandler);
 52	
 53	export default {
 54	  fetch: (request: Request) =>
 55	    // A standard HTML form remains usable without JavaScript. Its checked
 56	    // request reaches the same named RPC client through the private binding.
 57	    // Only plain, Schema-encoded form/report data reaches TanStack rendering.
 58	    appRuntime.runPromise(
 59	      Effect.gen(function* websiteRequest() {
 60	        const url = new URL(request.url);
 61	        if (url.pathname.startsWith("/ingest/")) {
 62	          const relay = yield* WebsiteAnalyticsRelay;
 63	          const incoming = yield* HttpServerRequest.HttpServerRequest;
 64	          return yield* relay.handle(incoming).pipe(
 65	            Effect.catchTag("WebsiteRelayFailure", (error) =>
 66	              Effect.succeed(
 67	                HttpServerResponse.empty({
 68	                  headers: { "cache-control": "no-store" },
 69	                  status: Match.value(error.reason).pipe(
 70	                    Match.when("configuration", () => 503),
 71	                    Match.when("origin", () => 403),
 72	                    Match.whenOr("metadata", "request", () => 400),
 73	                    Match.when("request-size", () => 413),
 74	                    Match.whenOr(
 75	                      "transport",
 76	                      "redirect",
 77	                      "response-size",
 78	                      () => 502
 79	                    ),
 80	                    Match.when("deadline", () => 504),
 81	                    Match.exhaustive
 82	                  ),
 83	                })
 84	              )
 85	            )
 86	          );
 87	        }
 88	        const discoveryPath = url.pathname;
 89	        if (Schema.is(DocsDiscoveryPath)(discoveryPath)) {
 90	          if (request.method !== "GET" && request.method !== "HEAD") {
 91	            return HttpServerResponse.empty({
 92	              headers: { allow: "GET, HEAD" },
 93	              status: 405,
 94	            });
 95	          }
 96	          if (url.search !== "") {
 97	            return HttpServerResponse.empty({ status: 400 });
 98	          }
 99	          const application = yield* WebsiteServerApplication;
100	          return yield* application.docsDiscovery(discoveryPath).pipe(
101	            Effect.map((document) => {
102	              const headers = {
103	                "cache-control": "public, max-age=300",
104	                "content-type": `${document.contentType}; charset=utf-8`,
105	                "x-content-type-options": "nosniff",
106	              };
107	              return request.method === "HEAD"
108	                ? HttpServerResponse.empty({ headers, status: 200 })
109	                : HttpServerResponse.text(document.body, {
110	                    contentType: `${document.contentType}; charset=utf-8`,
111	                    headers,
112	                  });
113	            }),
114	            Effect.catch(() =>
115	              Effect.succeed(
116	                HttpServerResponse.empty({
117	                  headers: { "cache-control": "no-store" },
118	                  status: 503,
119	                })
120	              )
121	            )
122	          );
123	        }
124	        const calculatorId = Match.value(url.pathname).pipe(
125	          Match.when("/calculators/au.income-tax.annual", () =>
126	            AuAnnualTaxCalculatorId.make("au.income-tax.annual")
127	          ),
128	          Match.when("/calculators/au.pay.withholdings", () =>
129	            AuPayCalculatorId.make("au.pay.withholdings")
130	          ),
131	          Match.when("/", () => AuPayCalculatorId.make("au.pay.take-home")),
132	          Match.orElse(() => null)
133	        );
134	        if (url.pathname.startsWith(`${WebsiteServerFunctionBase}/`)) {
135	          if (
136	            url.pathname !== WebsiteSettingsFunctionPath &&
137	            url.pathname !== WebsiteDocsPageFunctionPath &&
138	            url.pathname !== WebsiteDocsSearchFunctionPath
139	          ) {
140	            return HttpServerResponse.empty({ status: 404 });
141	          }
142	          // The native GET functions take no data or client Context. Reject
143	          // representation input before the framework's
144	          // JSON/FormData parser can reflect it in an unexpected error.
145	          if (request.method !== "GET") {
146	            return HttpServerResponse.empty({
147	              headers: { allow: "GET" },
148	              status: 405,
149	            });
150	          }
151	          if (
152	            url.search !== "" ||
153	            request.headers.has("content-type") ||
154	            (url.pathname === WebsiteDocsSearchFunctionPath &&
155	              !Schema.is(Schema.toEncoded(WebsiteDocsSearchHeader))(
156	                request.headers.get("x-taxkit-docs-search")
157	              )) ||
158	            (url.pathname === WebsiteDocsPageFunctionPath &&
159	              !Schema.is(DocsPublicPagePath)(
160	                request.headers.get("x-taxkit-docs-page")
161	              ))
162	          ) {
163	            return HttpServerResponse.empty({ status: 400 });
164	          }
165	        }
166	
167	        return yield* request.method !== "POST" || calculatorId === null
168	          ? Effect.gen(function* websiteHtml() {
169	              const incoming = yield* HttpServerRequest.HttpServerRequest;
170	              const htmlRequest = yield* HttpServerRequest.toWeb(incoming).pipe(
171	                Effect.orDie
172	              );
173	              return yield* Effect.promise(() =>
174	                Promise.resolve(render(htmlRequest, { context: {} }))
175	              ).pipe(Effect.map(HttpServerResponse.fromWeb));
176	            }).pipe(withDocsRepresentation)
177	          : withCalculatorRequestBodyLimit(
178	              Effect.gen(function* () {
179	                const incoming = yield* HttpServerRequest.HttpServerRequest;
180	                const bounded = yield* HttpServerRequest.toWeb(incoming, {
181	                  signal: request.signal,
182	                });
183	                const data = yield* Effect.tryPromise({
184	                  catch: () =>
185	                    new WebsiteInputError({
186	                      message: "Enter a valid pay amount and pay period.",
187	                    }),
188	                  try: () => bounded.formData(),
189	                });
190	                const decodedForm: Effect.Effect<
191	                  WebsiteCalculatorForm,
192	                  Schema.SchemaError
193	                > =
194	                  calculatorId === "au.income-tax.annual"
195	                    ? Schema.decodeUnknownEffect(AnnualTaxForm)({
196	                        taxableDollars: data.get("taxableDollars"),
197	                      })
198	                    : Schema.decodeUnknownEffect(TakeHomeForm)({
199	                        grossDollars: data.get("grossDollars"),
200	                        period: data.get("period"),
201	                        taxFreeThresholdClaimed:
202	                          data.get("taxFreeThresholdClaimed") === "on",
203	                      });
204	                const form = yield* decodedForm.pipe(
205	                  Effect.mapError(
206	                    () =>
207	                      new WebsiteInputError({
208	                        message: "Enter a valid pay amount and pay period.",
209	                      })
210	                  )
211	                );
212	                const result = yield* (
213	                  Schema.is(AnnualTaxForm)(form)
214	                    ? annualTaxRequestFromForm(form)
215	                    : takeHomeRequestFromForm(
216	                        form,
217	                        AuPayCalculatorId.make(
218	                          calculatorId === "au.pay.withholdings"
219	                            ? "au.pay.withholdings"
220	                            : "au.pay.take-home"
221	                        )
222	                      )
223	                ).pipe(
224	                  Effect.fromResult,
225	                  Effect.flatMap((input) =>
226	                    WebsiteServerApplication.pipe(
227	                      Effect.flatMap((application) =>
228	                        application.calculate(input)
229	                      )
230	                    )
231	                  ),
232	                  Effect.result
233	                );
234	                const submission = yield* Schema.encodeEffect(
235	                  WebsiteSubmissionTransport
236	                )(WebsiteSubmission.make({ calculatorId, form, result })).pipe(
237	                  Effect.orDie
238	                );
239	                const headers = new Headers(request.headers);
240	                headers.delete("content-length");
241	                headers.delete("content-type");
242	                const response = yield* Effect.promise(() =>
243	                  Promise.resolve(
244	                    render(
245	                      new Request(request.url, {
246	                        headers,
247	                        method: "GET",
248	                        signal: request.signal,
249	                      }),
250	                      { context: { submission } }
251	                    )
252	                  )
253	                );
254	                return HttpServerResponse.fromWeb(response);
255	              }),
256	              CalculatorRequestBodyPolicy.make({ responseFormat: "html" })
257	            ).pipe(
258	              Effect.catchTag("WebsiteInputError", () =>
259	                Effect.succeed(HttpServerResponse.empty({ status: 400 }))
260	              )
261	            );
262	      }).pipe(
263	        // Native HTTP failure matching preserves aborts and safe empty errors.
264	        // The installed host reporter discards arbitrary Causes before logging.
265	        Effect.catchCause((cause) =>
266	          HttpServerError.causeResponse(cause).pipe(
267	            Effect.flatMap(([response, reportable]) =>
268	              ErrorReporter.report(reportable).pipe(Effect.as(response))
269	            )
270	          )
271	        ),
272	        Effect.provideService(
273	          CalculatorRequestRateKey,
274	          calculatorEdgeRateKey(EffectHeaders.fromInput(request.headers))
275	        ),
276	        Effect.provideService(
277	          HttpServerRequest.HttpServerRequest,
278	          HttpServerRequest.fromWeb(request)
279	        ),
280	        Effect.scoped,
281	        Effect.map(HttpServerResponse.toWeb)
282	      ),
283	      { signal: request.signal }
284	    ),
285	};
  1	import type {
  2	  loadWebsiteDocsSearch,
  3	  loadWebsiteDocsPage,
  4	  loadWebsiteSettings,
  5	} from "./loaders";
  6	
  7	export interface RouterContext {
  8	  readonly loadDocsSearch: typeof loadWebsiteDocsSearch;
  9	  readonly loadDocsPage: typeof loadWebsiteDocsPage;
 10	  readonly loadSettings: typeof loadWebsiteSettings;
 11	}

  1	import { createServerFn } from "@tanstack/react-start";
  2	import { Effect, Result, Schema } from "effect";
  3	
  4	import type { readDocsSearchLocation } from "./docs/search-location.boundary";
  5	import {
  6	  loadWebsiteDocsSearchServer,
  7	  loadWebsiteDocsPageServer,
  8	  loadWebsiteSettingsServer,
  9	} from "./loaders.server";
 10	import { WebsiteDocsSearchHeader, WebsiteDocsSearchTransport } from "./schemas";
 11	import type { WebsiteServerRenderContext } from "./schemas";
 12	
 13	const websiteSettings = createServerFn({ method: "GET" }).handler(() =>
 14	  loadWebsiteSettingsServer()
 15	);
 16	// Use the native generated identity at ingress; never mirror a build-time ID.
 17	export const WebsiteSettingsFunctionPath = websiteSettings.url;
 18	const websiteDocsPage = createServerFn({ method: "GET" }).handler(() =>
 19	  loadWebsiteDocsPageServer()
 20	);
 21	export const WebsiteDocsPageFunctionPath = websiteDocsPage.url;
 22	
 23	export const loadWebsiteDocsPage = (options: {
 24	  readonly path: string;
 25	  readonly signal: AbortSignal;
 26	}) =>
 27	  Effect.runPromise(
 28	    Effect.promise(() =>
 29	      websiteDocsPage({
 30	        headers: { "x-taxkit-docs-page": options.path },
 31	        signal: options.signal,
 32	      })
 33	    ),
 34	    { signal: options.signal }
 35	  );
 36	
 37	const websiteDocsSearch = createServerFn({ method: "GET" }).handler(() =>
 38	  loadWebsiteDocsSearchServer()
 39	);
 40	export const WebsiteDocsSearchFunctionPath = websiteDocsSearch.url;
 41	export const loadWebsiteDocsSearch = (options: {
 42	  readonly query: ReturnType<typeof readDocsSearchLocation>;
 43	  readonly signal: AbortSignal;
 44	}) =>
 45	  Effect.runPromise(
 46	    Effect.gen(function* () {
 47	      const query = yield* Effect.fromResult(options.query);
 48	      const header = yield* Schema.encodeEffect(WebsiteDocsSearchHeader)(
 49	        query.term ?? ""
 50	      ).pipe(Effect.orDie);
 51	      return yield* Effect.promise(() =>
 52	        websiteDocsSearch({
 53	          headers: { "x-taxkit-docs-search": header },
 54	          signal: options.signal,
 55	        })
 56	      );
 57	    }).pipe(
 58	      Effect.catchTag("DocsSearchInputError", (error) =>
 59	        Schema.encodeEffect(WebsiteDocsSearchTransport)(
 60	          Result.fail(error)
 61	        ).pipe(Effect.orDie)
 62	      )
 63	    ),
 64	    { signal: options.signal }
 65	  );
 66	
 67	// The framework owns this plain Promise transport. Its small Effect carries
 68	// the request signal and encoded SSR submission; it owns no client or Layer.
 69	export const loadWebsiteSettings = (options: {
 70	  readonly signal: AbortSignal;
 71	  readonly submission?: WebsiteServerRenderContext["submission"];
 72	}) =>
 73	  Effect.runPromise(
 74	    Effect.promise(() => websiteSettings({ signal: options.signal })).pipe(
 75	      Effect.map((bootstrap) => ({
 76	        catalogue: "catalogue" in bootstrap ? bootstrap.catalogue : undefined,
 77	        settings: "settings" in bootstrap ? bootstrap.settings : undefined,
 78	        submission: options.submission,
 79	      }))
 80	    ),
 81	    { signal: options.signal }
 82	  );
  1	import "@tanstack/react-start/server-only";
  2	import { notFound } from "@tanstack/react-router";
  3	import { getRequest } from "@tanstack/react-start/server";
  4	import { DocsPageUnavailable } from "@taxkit/api-rpc/content/errors";
  5	import { DocsPublicPagePath } from "@taxkit/content/schemas";
  6	import { Array, Cause, Effect, ErrorReporter, Schema } from "effect";
  7	import { HttpServerError, HttpServerResponse } from "effect/http";
  8	
  9	import { WebsiteServerFunctionBase } from "./config";
 10	import { DocsSearchInputError } from "./docs/errors";
 11	import { preloadDocsPresentation } from "./docs/mdx.boundary";
 12	import { appRuntime } from "./runtime.server";
 13	import {
 14	  WebsiteDocsSearchHeader,
 15	  WebsiteDocsSearchLocation,
 16	  WebsiteDocsSearchTransport,
 17	  WebsiteCatalogueTransport,
 18	  WebsiteDocsPageTransport,
 19	  WebsiteSettingsTransport,
 20	} from "./schemas";
 21	import { WebsiteServerApplication } from "./service.server";
 22	
 23	export const loadWebsiteSettingsServer = () =>
 24	  appRuntime.runPromise(
 25	    WebsiteServerApplication.pipe(
