  2	import { Duration, Effect, Option, Result, Schema, Stream } from "effect";
  3	import * as Atom from "effect/reactivity/Atom";
  4	import * as AtomRegistry from "effect/reactivity/AtomRegistry";
  5	
  6	import { registerWebsiteBrowserTools } from "./browser-tools.boundary";
  7	import { WebsiteBrowserToolFailure } from "./browser-tools.schemas";
  8	import { WebsiteBrowserToolkit } from "./browser-tools.toolkit";
  9	import {
 10	  calculatorPageAtoms,
 11	  calculatorRuntime,
 12	  publicSettingsAtom,
 13	  websiteCatalogueAtom,
 14	} from "./calculator.atoms";
 15	import { AnnualTaxForm, TakeHomeForm } from "./form.boundary";
 16	
 17	// One mounted calculator owns these registrations and callbacks through its
 18	// existing React runtime. Handlers invoke its existing edit/submit commands;
 19	// they neither acquire another client nor perform their own calculation.
 20	export const browserCalculatorToolsAtom = Atom.family(
 21	  (calculatorId: CalculatorRunServiceRequest["calculatorId"]) => {
 22	    const page = calculatorPageAtoms(calculatorId);
 23	    return calculatorRuntime.fn<"register">()((_, get) =>
 24	      Effect.gen(function* () {
 25	        const settings = get.registry.get(publicSettingsAtom);
 26	        if (Option.isNone(settings)) {
 27	          return;
 28	        }
 29	        // Reads made by a later native callback do not retain an idle atom.
 30	        // Hold the current attempt for this page's entire registration lifetime.
 31	        get.mount(page.attempt);
 32	        const handlers = yield* WebsiteBrowserToolkit.toHandlers({
 33	          taxkit_calculate_visible_form: Effect.fn(
 34	            "WebsiteBrowserTools.calculateVisibleForm"
 35	          )(() =>
 36	            Effect.gen(function* () {
 37	              // Admission and visible submission are one synchronous registry
 38	              // command. Two tool calls cannot both claim the same idle form.
 39	              const owned = yield* Effect.sync(() => {
 40	                if (get.registry.get(page.view).busy) {
 41	                  return Result.fail(
 42	                    new WebsiteBrowserToolFailure({
 43	                      code: "calculation-busy",
 44	                      retry: "wait-then-try-manually",
 45	                    })
 46	                  );
 47	                }
 48	                get.set(page.submit, "calculate");
 49	                return get.registry.get(page.attempt).pipe(
 50	                  Option.match({
 51	                    onNone: () =>
 52	                      Result.fail(
 53	                        new WebsiteBrowserToolFailure({
 54	                          code: "invalid-input",
 55	                          retry: "check-the-visible-form",
 56	                        })
 57	                      ),
 58	                    onSome: Result.succeed,
 59	                  })
 60	                );
 61	              }).pipe(Effect.flatMap(Effect.fromResult));
 62	              yield* AtomRegistry.getResult(get.registry, page.calculation, {
 63	                suspendOnWaiting: true,
 64	              }).pipe(
 65	                Effect.raceFirst(
 66	                  AtomRegistry.toStream(get.registry, page.attempt).pipe(
 67	                    Stream.filter(
 68	                      (current) =>
 69	                        Option.isNone(current) || current.value !== owned
 70	                    ),
 71	                    Stream.take(1),
 72	                    Stream.runDrain,
 73	                    Effect.andThen(Effect.interrupt)
 74	                  )
 75	                ),
 76	                Effect.mapError(
 77	                  () =>
 78	                    new WebsiteBrowserToolFailure({
 79	                      code: "service-unavailable",
 80	                      retry: "try-again-manually",
 81	                    })
 82	                ),
 83	                Effect.timeoutOrElse({
 84	                  duration: Duration.seconds(12),
 85	                  orElse: () =>
 86	                    Effect.fail(
 87	                      new WebsiteBrowserToolFailure({
 88	                        code: "service-unavailable",
 89	                        retry: "try-again-manually",
 90	                      })
 91	                    ),
 92	                }),
 93	                Effect.onExit(() =>
 94	                  Effect.sync(() => {
 95	                    // Cancel only unfinished work still owned by this call. A
 96	                    // newer manual request must survive an older tool's cleanup.
 97	                    if (
 98	                      get.registry.get(page.view).busy &&
 99	                      get.registry
100	                        .get(page.attempt)
101	                        .pipe(Option.exists((current) => current === owned))
102	                    ) {
103	                      get.set(page.cancel, "cancel");
104	                    }
105	                  })
106	                )
107	              );
108	              const current = get.registry.get(page.view);
109	              if (
110	                !get.registry
111	                  .get(page.attempt)
112	                  .pipe(Option.exists((attempt) => attempt === owned))
113	              ) {
114	                return yield* Effect.interrupt;
115	              }
116	              if (current.stale || Option.isNone(current.report)) {
117	                return yield* Effect.fail(
118	                  new WebsiteBrowserToolFailure({
119	                    code: "no-current-result",
120	                    retry: "try-again-manually",
121	                  })
122	                );
123	              }
124	              return current;
125	            })
126	          ),
127	          taxkit_fill_calculator: Effect.fn(
128	            "WebsiteBrowserTools.fillCalculator"
129	          )((form) =>
130	            Effect.sync(() => {
131	              if (
132	                !(calculatorId === "au.income-tax.annual"
133	                  ? Schema.is(AnnualTaxForm)(form)
134	                  : Schema.is(TakeHomeForm)(form))
135	              ) {
136	                return Result.fail(
137	                  new WebsiteBrowserToolFailure({
138	                    code: "invalid-input",
139	                    retry: "check-the-visible-form",
140	                  })
141	                );
142	              }
143	              get.set(page.edit, form);
144	              return Result.succeed(get.registry.get(page.view));
145	            }).pipe(Effect.flatMap(Effect.fromResult))
146	          ),
147	          taxkit_find_calculators: Effect.fn(
148	            "WebsiteBrowserTools.findCalculators"
149	          )(() =>
150	            Effect.sync(() => get.registry.get(websiteCatalogueAtom)).pipe(
151	              Effect.flatMap(
152	                Option.match({
153	                  onNone: () =>
154	                    Effect.fail(
155	                      new WebsiteBrowserToolFailure({
156	                        code: "service-unavailable",
157	                        retry: "try-again-manually",
158	                      })
159	                    ),
160	                  onSome: Effect.succeed,
161	                })
162	              )
163	            )
164	          ),
165	          taxkit_read_calculator: Effect.fn(
166	            "WebsiteBrowserTools.readCalculator"
167	          )(() => Effect.sync(() => get.registry.get(page.view))),
168	          taxkit_read_result: Effect.fn("WebsiteBrowserTools.readResult")(() =>
169	            Effect.sync(() => get.registry.get(page.view))
170	          ),
171	        });
172	        const toolkit = yield* WebsiteBrowserToolkit.pipe(
173	          Effect.provide(handlers)
174	        );
175	        yield* registerWebsiteBrowserTools(
176	          toolkit,
177	          settings.value.websiteOrigin
178	        );
179	        // Retain the callback scope until React releases this page atom. The
180	        // registration adapter removes tools and interrupts its fibre set.
181	        return yield* Effect.never;
182	      })
183	    );
184	  }
185	);

